repo.donations.py:
"""Donation records."""


class Donation:
    def __init__(self, donor, pounds):
        self.donor = donor
        self.pounds = pounds

    def __repr__(self):
        return "Donation(%r, %r)" % (self.donor, self.pounds)


ROWS = [('mia', 7), ('noor', 38), ('mia', 51), ('pia', 12), ('mia', 48)]


def load_donations():
    """Yield the stored donations one at a time."""
    for donor, pounds in ROWS:
        yield Donation(donor, pounds)

repo.settle.py:
"""Checking that donations add up."""


def is_settled(donations, expected_total):
    """Return True when the pounds of the donations add up to expected_total. pounds may be fractional."""
    return sum(x.pounds for x in donations) == expected_total


def shortfall(donations, expected_total):
    """Return how much pounds is still missing, never less than 0."""
    return max(0, expected_total - sum(x.pounds for x in donations))


def group_by_donor(donations):
    """Return a dict from donor to the list of donations with that donor."""
    groups = {}
    for x in donations:
        groups.setdefault(x.donor, []).append(x)
    return groups

